public enum ModoP107 {
    EPP(1), TESOFE(2), TODO(3);
    final int valor;
    ModoP107(int v) { valor = v; }
    boolean incluyeEpp()    { return this == EPP || this == TODO; }
    boolean incluyeTesofe() { return this == TESOFE || this == TODO; }

    /** W88-TASK-VAL-OK: cualquier otro valor aborta (CHANGE ATTRIBUTE STATUS OF MYSELF TO -1). */
    static ModoP107 de(long taskValue) {
        return Arrays.stream(values()).filter(m -> m.valor == taskValue).findFirst()
                .orElseThrow(() -> new JobParametersInvalidException("ERROR TASK VALUE " + taskValue));
    }
}

@Bean
Job comisionesEppTesofe(JobRepository repo, Step fechasLote, Step cargaTablaEpp,
                        Step revisaComisiones, Step revisaAsistencias, Step generaCompendepp,
                        Step procesoTesofe, JobExecutionDecider modoDecider) {
    return new JobBuilder("S500P107", repo)
            .validator(p -> ModoP107.de(p.getLong("modo")))
            .start(fechasLote)                                       // 40005000-VALIDO-FECHA-PRO
            .next(modoDecider).on("TESOFE").to(procesoTesofe)
            .from(modoDecider).on("*").to(cargaTablaEpp)             // EPP o TODO
              .next(revisaComisiones).next(revisaAsistencias).next(generaCompendepp)
              .next(modoDecider).on("TODO").to(procesoTesofe)
            .end().build();
}

@Component
@RequiredArgsConstructor
public class FechasLoteTasklet implements Tasklet {

    private final ControlCaptacionRepository control;   // S500B02CONTROL

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var b02 = control.findControl().orElseThrow();
        LocalDate fecBase = b02.fechaLote();            // WKS-FEC-BASE, AAAAMMDD
        LocalDate fecProx = b02.fechaLinea();           // WKS-FEC-PROX
        boolean esMensual = fecProx.getMonthValue() != fecBase.getMonthValue();   // WKS-ES-MENSUAL

        var job = ctx.getStepContext().getStepExecution().getJobExecution().getExecutionContext();
        job.put("fecBase", fecBase);
        job.put("fecProx", fecProx);
        job.put("esMensual", esMensual);
        return RepeatStatus.FINISHED;
    }
}

@Component
@RequiredArgsConstructor
public class TablaVigenciaEpp {

    private final ClavesPorFuncionRepository b17;   // S500B17CVESXFUN
    private final CalendarioBancario locsup;        // S006LOCSUP

    public record Vigencia(int mesesVigencia, int indicadorVencimiento, LocalDate fechaProyectada) {}
    private final Map<Integer, Vigencia> porClave = new HashMap<>();   // WS-EPP-TABLA OCCURS 10000

    public void carga(LocalDate fecBase) {
        Map<Integer, LocalDate> proyectadaPorMeses = new HashMap<>();
        for (var r : b17.findAll()) {
            int clave = r.claveTransaccion();
            if (r.mesesVigencia() <= 0 || clave <= 0 || clave >= 10_000) continue;
            // LOCSUP función 22, formato 13: fecha base desplazada N meses ("PROY-FECH-ATRAS")
            LocalDate proy = proyectadaPorMeses.computeIfAbsent(r.mesesVigencia(),
                    m -> locsup.funcion22(fecBase, m)
                               .orElseThrow(() -> new IllegalStateException("LOCSUP sin fecha para " + m)));
            porClave.put(clave, new Vigencia(r.mesesVigencia(), r.indicadorVencimiento(), proy));
        }
    }

    public Optional<Vigencia> de(int claveCobro) { return Optional.ofNullable(porClave.get(claveCobro)); }
}

@Bean
Step revisaComisiones(JobRepository repo, PlatformTransactionManager tx, P107Properties props,
                      JpaPagingItemReader<ComisionEpp> b49,          // SET S500B49COMPENDEPP TO BEGINNING
                      RevisaComisionProcessor revisa,
                      JpaItemWriter<ComisionEpp> writer) {
    return new StepBuilder("revisaComisiones", repo)
            .<ComisionEpp, ComisionEpp>chunk(props.bloqueTransaccionEpp(), tx)   // W77-BLQ-STORE = 100
            .reader(b49)
            .processor(revisa)
            .writer(writer)
            .faultTolerant()
            .skip(OptimisticLockingFailureException.class).skipLimit(0)   // el fuente ignora el estatus 15; aquí no
            .build();
}

@Component
@StepScope
@RequiredArgsConstructor
public class RevisaComisionProcessor implements ItemProcessor<ComisionEpp, ComisionEpp> {

    static final int ACTIVA = 0, VENCIDA = 3, PAGADA = 4;

    private final TablaVigenciaEpp vigencias;
    @Value("#{jobExecutionContext['fecBase']}") private LocalDate fecBase;

    @Override
    public ComisionEpp process(ComisionEpp c) {
        if (c.getStatus() != ACTIVA) return null;                      // solo comisiones activas
        if (c.getSaldo().signum() == 0) {                              // 50001300-COMISION-PAGADA
            return c.marca(PAGADA, fecBase);
        }
        return vigencias.de(c.getClaveCobro())                         // 50001620-VALIDA-CLAVE
                .filter(v -> v.mesesVigencia() > 0 && v.indicadorVencimiento() == 0)
                .filter(v -> c.getFechaLinea().isBefore(v.fechaProyectada()))   // 50001630
                .map(v -> c.marca(VENCIDA, fecBase))
                .orElse(null);                                         // sin cambio: no se reescribe
    }
}

@Entity @Table(name = "S500B49COMPENDEPP")
public class ComisionEpp {
    @EmbeddedId private ComisionEppId id;          // contrato + clave de cobro + fecha de línea
    private int status;
    @Column(precision = 15, scale = 2) private BigDecimal saldo;
    private LocalDate fechaLinea, fechaUltact, fechaUltpago;
    private int claveCobro;

    ComisionEpp marca(int nuevoStatus, LocalDate fecha) {
        this.status = nuevoStatus;
        this.fechaUltact = fecha;                  // MOVE WKS-FEC-BASE TO B49-FECHA-ULTACT
        return this;
    }
}

@Bean
Step generaCompendepp(JobRepository repo, PlatformTransactionManager tx,
                      JpaPagingItemReader<ComisionEpp> b49Lectura,       // FIND NEXT, sin bloqueo
                      FlatFileItemWriter<ComisionEpp> compendepp) {      // header, detalle y trailer
    return new StepBuilder("generaCompendepp", repo)
            .<ComisionEpp, ComisionEpp>chunk(192, tx)                   // 192 registros por bloque
            .reader(b49Lectura)
            .processor(seleccionArchivo(null, null))
            .writer(compendepp)
            .build();
}

@Bean @StepScope
ItemProcessor<ComisionEpp, ComisionEpp> seleccionArchivo(
        @Value("#{jobExecutionContext['esMensual']}") Boolean esMensual,
        @Value("#{jobExecutionContext['fecBase']}") LocalDate fecBase) {
    return c -> {
        if (esMensual) return c;                                       // 50003300-BARRE-TODO
        boolean tocadaHoy = fecBase.equals(c.getFechaUltact())
                         || fecBase.equals(c.getFechaUltpago());        // 50003200-BARRE-XFEHCA
        return tocadaHoy ? c : null;
    };
}

