@Service
@RequiredArgsConstructor
public class AvisoS151 {

    private final RegistroContableS151 registra;   // S151REGISTRA, función 1 (CARGAMOV1)
    private final P107Properties props;

    /** 500042500-500-DIFERENCIA: solo se avisa si alguna de las tres diferencias es distinta de cero. */
    public void avisaSiHayDiferencia(FamiliaTesofe f, LocalDate fecBase) {
        if (f.difDisponible().signum() == 0 && f.difTecho().signum() == 0
                && f.difBloqueado().signum() == 0) return;

        var mov = MovimientoS151.builder()
                .funcion(1).formato(1).sistema(500).sistemaOrigen(500)
                .producto(f.producto()).instrumento(f.instrumento()).moneda(f.moneda())
                .sucursal(props.sucursalPromotoraS015()).caja(props.s151().caja())
                .cuenta(f.cuentaControl())
                .claveTransaccion(props.s151().claveDiferencia())
                // el importe está comentado en el fuente (línea 1694): el aviso viaja sin importe
                .fechaContable(fecBase).fechaValor(fecBase)
                .banco(props.s151().banco()).tipoProceso(props.s151().tipoProceso()).origen(1)
                .nodoOrigen(props.csi())
                .build();
        var r = registra.cargaMov1(mov);
        if (r.status() > 0) throw new AvisoS151Exception("ERR FUNCION 1 LIB S151 DIF-TESO", r);
    }
}

/** 50004400-600-VAL-SAL-BLO: decide si se reinicia el árbol TESOFE de la cuenta control. */
@Component
public class ReinicioTesofePolicy {

    static final int BLOQUEO_TESOFE = 14;

    public boolean reinicia(ContratoCaptacion b03) {
        boolean sinBloqueoTesofe = b03.impSolBloTes().signum() == 0;
        int st = b03.status(), tipo = b03.tipoBloqueo();
        boolean bloqueoGeneral = b03.impSolBloq().signum() > 0;

        if (sinBloqueoTesofe && st == 1 && tipo != BLOQUEO_TESOFE)              return true;
        if (sinBloqueoTesofe && st == 1 && tipo == BLOQUEO_TESOFE && bloqueoGeneral)  return true;
        if (sinBloqueoTesofe && st == 0 && tipo == 0 && bloqueoGeneral)         return true;
        if (sinBloqueoTesofe && st == 1 && tipo == BLOQUEO_TESOFE && !bloqueoGeneral) return false;
        if (sinBloqueoTesofe && st < 2)                                         return true;
        return false;   // IMPSOLBLO-TES > 0 o STATUS > 1: solo se limpia el indicador de reinicio
    }
}
